import{_ as s,C as n,o as l,c as d,j as a,a as e,E as i,a3 as o}from"./chunks/framework.CZBGEXos.js";const q=JSON.parse('{"title":"Ticks","description":"","frontmatter":{},"headers":[],"relativePath":"uk/tools/ticks.md","filePath":"uk/tools/ticks.md"}'),h={name:"uk/tools/ticks.md"};function c(p,t,u,m,g,b){const r=n("Screenshot");return l(),d("div",null,[t[0]||(t[0]=a("h1",{id:"ticks",tabindex:"-1"},[e("Ticks "),a("a",{class:"header-anchor",href:"#ticks","aria-label":'Permalink to "Ticks"'},"​")],-1)),t[1]||(t[1]=a("p",null,[e("Ticks — це стрічка "),a("strong",null,"великих угод"),e(". Вона показує агресивні купівлі й продажі, що перевищили заданий вами розмір, у момент друку, згруповані по одній картці на символ. На тому самому потоці вона також може знаходити "),a("strong",null,"TWAP-ланцюжки"),e(" — той самий розмір ордера, що повторюється на одній біржі. Саме так виглядає алгоритм, який нарізає великий ордер на шматки.")],-1)),i(r,{src:"ticks",alt:"Вікно Ticks із кількома картками символів",caption:"Вікно Ticks"}),t[2]||(t[2]=o('<p>Якщо <a href="/manual/uk/tools/knives.html">Knives</a> каже, що свічка зрушила, то Ticks показує окремі угоди, які її зрушили.</p><h2 id="що-таке-тік" tabindex="-1">Що таке тік <a class="header-anchor" href="#що-таке-тік" aria-label="Permalink to &quot;Що таке тік&quot;">​</a></h2><p>Тік — це один <strong>сплеск</strong> (burst): послідовні принти від того самого агресора, на тій самій біржі й символі, об&#39;єднані в одну подію. Ринковий ордер, що пройшов десять цінових рівнів, друкує десять виконань; Ticks показує їх як один тік із сумарним розміром у доларах, рухом ціни, який він спричинив, і кількістю принтів усередині.</p><p>Сплески формуються й фільтруються на сервері. Клієнт отримує лише ті тіки, що вже пройшли ваші фільтри розміру, руху, сторони й символів.</p><h3 id="біржі" tabindex="-1">Біржі <a class="header-anchor" href="#біржі" aria-label="Permalink to &quot;Біржі&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Біржа</th><th>Ринок</th></tr></thead><tbody><tr><td>Binance</td><td>Perp і spot</td></tr><tr><td>Bybit</td><td>Perp і spot</td></tr><tr><td>OKX</td><td>Perp</td></tr><tr><td>Gate.io</td><td>Perp і spot</td></tr><tr><td>Hyperliquid</td><td>Perp</td></tr><tr><td>Kraken</td><td>Spot</td></tr></tbody></table><p>Kraken використовується лише тут — жоден інший інструмент його не читає.</p><h2 id="як-читати-вікно" tabindex="-1">Як читати вікно <a class="header-anchor" href="#як-читати-вікно" aria-label="Permalink to &quot;Як читати вікно&quot;">​</a></h2><h3 id="заголовок-вікна" tabindex="-1">Заголовок вікна <a class="header-anchor" href="#заголовок-вікна" aria-label="Permalink to &quot;Заголовок вікна&quot;">​</a></h3><p>Зліва направо:</p><ul><li><strong>Таймфрейм</strong> — інтервал свічок для графіків усіх карток.</li><li><strong>Vol Ind</strong> — вмикає чи вимикає <a href="/manual/uk/customize/chart-colors.html#гістограма-обсягу">гістограму обсягу</a> на всіх графіках цього вікна.</li><li><strong>Mixed / Split</strong> — лише коли увімкнені TWAP-ланцюжки; див. <a href="#змішании-і-розділении-вигляд">Змішаний і розділений вигляд</a>.</li><li><strong>min $… · max $…</strong> — глобальний діапазон розміру сплеску, що зараз діє.</li><li><strong>ALL / ANY</strong> — <a href="#match-mode">режим збігу</a>.</li><li><strong>BOTH / BUY / SELL</strong> — яка сторона агресора враховується.</li><li><strong>…N more</strong> — сервер вперся у ваш <a href="#ліміт-доставки">ліміт доставки</a> і відкинув частину тіків. Пояснення нижче.</li><li><strong>Disconnected</strong> / <strong>Offline</strong> — стан з&#39;єднання.</li></ul><p>Поки нічого не пройшло фільтри, вікно показує <code>Listening</code> і діапазон розміру, на який воно налаштоване.</p><h3 id="картка-символу" tabindex="-1">Картка символу <a class="header-anchor" href="#картка-символу" aria-label="Permalink to &quot;Картка символу&quot;">​</a></h3><p>Для кожного символу є <strong>одна картка</strong>. Коли символ тікає знову — на будь-якій біржі — новий тік стає першим у списку картки, а сама картка переміщується на початок. На відміну від Knives, символ, що раз у раз друкує великі угоди, — це саме те, що треба побачити, тож він ніколи не вважається дублікатом.</p><p>У заголовку:</p><ul><li><strong>Іконка біржі</strong> — біржа, з якої малюється графік. Графік закріплюється за біржею, що дала <strong>перший</strong> тік символу.</li><li><strong>Символ</strong> — клацніть, щоб скопіювати.</li><li><strong>▲ / ▼</strong> — сторона останнього тіку: ▲ агресивна купівля, ▼ агресивний продаж.</li><li><strong>$ розмір</strong> — розмір сплеску цього тіку.</li><li><strong>% рух</strong> — наскільки змістилася ціна за цей сплеск.</li></ul><p>Під графіком — список тіків картки, найновіші зверху. Кожен рядок:</p><table tabindex="0"><thead><tr><th>Частина</th><th>Значення</th></tr></thead><tbody><tr><td>Час</td><td>Коли надрукувався сплеск</td></tr><tr><td>Іконка біржі</td><td>Де він надрукувався — може відрізнятися від біржі графіка</td></tr><tr><td>▲ / ▼</td><td>Сторона агресора</td></tr><tr><td>$</td><td>Розмір сплеску в доларах</td></tr><tr><td>Ціна</td><td>Останній принт сплеску — де зупинилась стрічка</td></tr><tr><td>%</td><td>Рух ціни за сплеск у напрямку агресора</td></tr><tr><td>×N.N</td><td>Якщо відомо: сплеск відносно середньої хвилини цього символу на цій біржі (див. <a href="#minimum-volume-ratio">коефіцієнт обсягу</a>)</td></tr><tr><td>N×</td><td>Скільки принтів об&#39;єднано. Наведіть, щоб побачити тривалість і найбільше окреме виконання</td></tr></tbody></table><p>Потягніть за маркер унизу будь-якої картки, щоб змінити висоту списку тіків. Висота застосовується до всіх карток.</p><p>Графіки в Ticks навмисно прості: без інструментів рисування, без повноекранного режиму й без шару мажорів. Ця стрічка — про те, що друкується зараз.</p><h3 id="ліміт-доставки" tabindex="-1">Ліміт доставки <a class="header-anchor" href="#ліміт-доставки" aria-label="Permalink to &quot;Ліміт доставки&quot;">​</a></h3><p>Якщо за секунду проходить більше тіків, ніж дозволяє <a href="#delivery-cap">ліміт доставки</a>, сервер першими відкидає <strong>найменші</strong> з утримуваних — ніколи не найновіші. Тоді в заголовку з&#39;являється <code>…N more</code>.</p><p>Біржа з низьким порогом розміру (Kraken можна опустити до $200) дає найменші тіки, тож вона першою замовкає в такій ситуації. Якщо біржа з низьким порогом постійно зникає, підніміть ліміт.</p><h2 id="twap-ланцюжки" tabindex="-1">TWAP-ланцюжки <a class="header-anchor" href="#twap-ланцюжки" aria-label="Permalink to &quot;TWAP-ланцюжки&quot;">​</a></h2><p>TWAP-ланцюжок — це <strong>той самий розмір тейкера, що повторюється</strong> на одній біржі, символі й стороні: наприклад, 0.5 BTC купується кожні 40 секунд. Алгоритми виконання саме так нарізають великі ордери, тож ланцюжок може виявити, що хтось набирає чи скидає позицію, навіть не надрукувавши жодної великої угоди.</p><p>TWAP-ланцюжки <strong>за замовчуванням вимкнені</strong> й повністю незалежні від потоку тіків: можна запускати будь-що одне або обидва разом.</p><div class="info custom-block"><p class="custom-block-title">Розділ TWAP з&#39;являється, лише коли його підтримує сервер</p><p>Розділ налаштувань прихований, доки сервер хоча б раз не повідомить про підтримку TWAP. Якщо ви його не бачите, відкрийте вікно Ticks, щоб воно під&#39;єдналося.</p></div><h3 id="картка-twap" tabindex="-1">Картка TWAP <a class="header-anchor" href="#картка-twap" aria-label="Permalink to &quot;Картка TWAP&quot;">​</a></h3><p>Картки TWAP мають той самий вигляд «графік зверху», що й картки тіків, — по одній на символ. У заголовку — сторона й сума найактивнішого останнім часом ланцюжка, та <code>×N</code> — скільки ланцюжків зараз має символ.</p><p>Кожен рядок — один ланцюжок:</p><table tabindex="0"><thead><tr><th>Частина</th><th>Значення</th></tr></thead><tbody><tr><td>▲ / ▼</td><td>Сторона</td></tr><tr><td>QTY / USD</td><td>Тип ланцюжка: однакова кількість монет щоразу чи однакова сума в доларах щоразу</td></tr><tr><td><code>0.5 ≈ $32K ×14</code></td><td>Середній розмір дочірнього ордера, його вартість і кількість повторів на цей момент</td></tr><tr><td>$</td><td>Скільки ланцюжок виконав загалом</td></tr><tr><td>Інтервал</td><td>Середній проміжок між повторами — справжні алгоритми рідко бувають ідеально регулярними</td></tr><tr><td>Тривалість</td><td>Скільки ланцюжок уже триває. Притлумлений рядок <strong>завершився</strong> — нових повторів якийсь час не було</td></tr><tr><td>%</td><td>Сукупний рух ціни від першого повтору</td></tr></tbody></table><p>Деякі рядки мають мітку:</p><ul><li><strong>2-SIDED</strong> — той самий розмір повторюється й на протилежній стороні. Зазвичай це маркетмейкер або бот обсягу, а не накопичення.</li><li><strong>ROUND</strong> — поширений круглий розмір. Може бути багато трейдерів, а не один.</li><li><strong>WEAK</strong> — на Binance, Bybit, OKX і Hyperliquid. На цих глибоких біржах однакові розміри часто — збіг дій багатьох трейдерів. Сприймайте як підказку.</li></ul><div class="warning custom-block"><p class="custom-block-title">Ланцюжок — це патерн, а не особа</p><p>Ніщо тут не доводить, що всі повтори поставив один учасник. Це лише розмір, що повторюється у стрічці. Читайте його разом із рухом ціни, а не замість нього.</p></div><h3 id="змішании-і-розділении-вигляд" tabindex="-1">Змішаний і розділений вигляд <a class="header-anchor" href="#змішании-і-розділении-вигляд" aria-label="Permalink to &quot;Змішаний і розділений вигляд&quot;">​</a></h3><p>Коли TWAP-ланцюжки увімкнені, кнопка в заголовку перемикає розкладку:</p><ul><li><strong>Mixed</strong> (за замовчуванням) — картки тіків і TWAP в одній сітці, відсортовані за свіжістю, з міткою <code>TICK</code> / <code>TWAP</code> на кожній.</li><li><strong>Split</strong> — картки TWAP отримують власну панель <code>TWAPS</code>. Перетягніть її заголовок, щоб пристикувати ліворуч, праворуч, зверху чи знизу, і тягніть розділювач, щоб змінити розмір. Працює так само, як <a href="/manual/uk/tools/alerts.html">стрічка ліквідацій</a> в Alerts.</li></ul><h2 id="налаштування" tabindex="-1">Налаштування <a class="header-anchor" href="#налаштування" aria-label="Permalink to &quot;Налаштування&quot;">​</a></h2><p>Відкрийте вкладку <strong>Ticks</strong> у головному вікні.</p>',39)),i(r,{src:"ticks-settings",alt:"Налаштування Ticks у головному вікні",caption:"Налаштування Ticks"}),t[3]||(t[3]=o('<h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><h4 id="enable-ticks-feed" tabindex="-1">Enable ticks feed <a class="header-anchor" href="#enable-ticks-feed" aria-label="Permalink to &quot;Enable ticks feed&quot;">​</a></h4><p>Вмикає чи вимикає стрічку великих угод. За замовчуванням увімкнено. На TWAP-ланцюжки не впливає.</p><h4 id="chart-timeframe" tabindex="-1">Chart timeframe <a class="header-anchor" href="#chart-timeframe" aria-label="Permalink to &quot;Chart timeframe&quot;">​</a></h4><p>Інтервал свічок для графіка кожної картки: від <code>1m</code> до <code>1w</code>. За замовчуванням <code>1m</code>.</p><h4 id="cards-kept" tabindex="-1">Cards kept <a class="header-anchor" href="#cards-kept" aria-label="Permalink to &quot;Cards kept&quot;">​</a></h4><p>Скільки карток символів вікно тримає, перш ніж витіснити найстарішу. Діапазон <strong>від 3 до 50</strong>, за замовчуванням 12.</p><h4 id="ticks-kept-per-card" tabindex="-1">Ticks kept per card <a class="header-anchor" href="#ticks-kept-per-card" aria-label="Permalink to &quot;Ticks kept per card&quot;">​</a></h4><p>Скільки тіків тримає список кожної картки, перш ніж відкинути найстаріший. Діапазон <strong>від 10 до 500</strong> з кроком 10, за замовчуванням 50.</p><h3 id="size-filters" tabindex="-1">Size filters <a class="header-anchor" href="#size-filters" aria-label="Permalink to &quot;Size filters&quot;">​</a></h3><h4 id="burst-size-range" tabindex="-1">Burst size range <a class="header-anchor" href="#burst-size-range" aria-label="Permalink to &quot;Burst size range&quot;">​</a></h4><p>Мінімальний і максимальний розмір сплеску в доларах. За замовчуванням мінімум <strong>$100 000</strong>, без максимуму.</p><p>Мінімум не може бути нижчим за серверний поріг, указаний в описі ($5 000 за замовчуванням). Залиште максимум порожнім, щоб не обмежувати.</p><div class="info custom-block"><p class="custom-block-title">Максимум — це виключення, а не збіг</p><p>Максимум діє завжди, навіть у режимі <strong>Any</strong>. Він потрібен, щоб відсікти найбільші принти — наприклад, щоб дивитися лише на потік середнього розміру.</p></div><p>Якщо максимум менший за мінімум, діапазон нічого не пропускає, і застосунок про це попереджає.</p><h4 id="match-mode" tabindex="-1">Match mode <a class="header-anchor" href="#match-mode" aria-label="Permalink to &quot;Match mode&quot;">​</a></h4><p>Як поєднуються три фільтри величини — мінімальний розмір, мінімальний рух ціни, мінімальний коефіцієнт обсягу. За замовчуванням <strong>All</strong>.</p><ul><li><strong>All</strong> — мають пройти всі задані фільтри.</li><li><strong>Any</strong> — достатньо одного.</li></ul><h4 id="price-move-range" tabindex="-1">Price move range <a class="header-anchor" href="#price-move-range" aria-label="Permalink to &quot;Price move range&quot;">​</a></h4><p>Мінімальний і максимальний рух ціни за сплеск у напрямку агресора. Діапазон <strong>від 0% до 5%</strong> (серверна стеля) з кроком 0.1%. Мінімум 0 = вимкнено, порожній максимум = без обмеження.</p><p>Рух проти агресора максимумом ніколи не відсікається.</p><h4 id="minimum-volume-ratio" tabindex="-1">Minimum volume ratio <a class="header-anchor" href="#minimum-volume-ratio" aria-label="Permalink to &quot;Minimum volume ratio&quot;">​</a></h4><p>Сплеск відносно середньої хвилини цього символу на цій біржі за останню годину. Діапазон <strong>від 0 до ×20</strong> з кроком ×0.5, за замовчуванням вимкнено.</p><p>×5 означає, що сам сплеск проторгував у п&#39;ять разів більше, ніж цей символ зазвичай торгує на цій біржі за цілу хвилину. Так ловляться угоди, великі <em>для цієї монети</em>, а не великі в доларах.</p><h4 id="side" tabindex="-1">Side <a class="header-anchor" href="#side" aria-label="Permalink to &quot;Side&quot;">​</a></h4><p>Яку сторону агресора враховувати: <strong>Both</strong>, <strong>Buy</strong> або <strong>Sell</strong>. За замовчуванням Both.</p><h3 id="venues" tabindex="-1">Venues <a class="header-anchor" href="#venues" aria-label="Permalink to &quot;Venues&quot;">​</a></h3><p>Окремий блок для кожної біржі. Кожну можна:</p><ul><li><strong>Вимкнути</strong> — з неї нічого не надходить.</li><li><strong>Дати власний діапазон розміру</strong> — замінює глобальний розмір сплеску лише для цієї біржі. $100K — буденність на перпах Binance і дуже велика угода на тонкому спотовому стакані, тож так обидва лишаються змістовними.</li><li><strong>Дати власний діапазон руху ціни</strong> — те саме для фільтра руху.</li></ul><p>Біржа без власних значень показує <code>global</code> і діапазон, за яким вона йде. Деякі біржі мають нижчий серверний поріг, ніж решта, — блок про це повідомляє. Їхні тіки найменші в потоці, тож саме їх першими відкидає <a href="#delivery-cap">ліміт доставки</a>.</p><p>Якщо вимкнено всі біржі, застосунок попереджає, що нічого не надійде.</p><h3 id="twap-chains" tabindex="-1">TWAP Chains <a class="header-anchor" href="#twap-chains" aria-label="Permalink to &quot;TWAP Chains&quot;">​</a></h3><h4 id="twap-chains-1" tabindex="-1">TWAP Chains <a class="header-anchor" href="#twap-chains-1" aria-label="Permalink to &quot;TWAP Chains&quot;">​</a></h4><p>Вмикає чи вимикає пошук TWAP-ланцюжків. <strong>За замовчуванням вимкнено.</strong></p><h4 id="cards-kept-1" tabindex="-1">Cards kept <a class="header-anchor" href="#cards-kept-1" aria-label="Permalink to &quot;Cards kept&quot;">​</a></h4><p>Ліміт карток TWAP. Окремий від ліміту карток тіків. Діапазон <strong>від 3 до 50</strong>, за замовчуванням 12.</p><h4 id="min-child-size" tabindex="-1">Min child size <a class="header-anchor" href="#min-child-size" aria-label="Permalink to &quot;Min child size&quot;">​</a></h4><p>Мінімальний середній розмір одного повтору в доларах. За замовчуванням <strong>$1 000</strong>. Серверного порогу немає: бувають справжні ланцюжки з повторами по $20.</p><h4 id="min-repeats" tabindex="-1">Min repeats <a class="header-anchor" href="#min-repeats" aria-label="Permalink to &quot;Min repeats&quot;">​</a></h4><p>Мінімальна кількість повторів на цей момент. Діапазон <strong>від 3 до 50</strong>, за замовчуванням 5. Будь-що менше за 3 сервер вважає за 3.</p><h4 id="min-total-size" tabindex="-1">Min total size <a class="header-anchor" href="#min-total-size" aria-label="Permalink to &quot;Min total size&quot;">​</a></h4><p>Мінімальна сума, яку ланцюжок уже виконав. Порожнє = вимкнено.</p><h4 id="min-price-move" tabindex="-1">Min price move <a class="header-anchor" href="#min-price-move" aria-label="Permalink to &quot;Min price move&quot;">​</a></h4><p>Мінімальний сукупний рух ціни на цей момент у напрямку агресора. Діапазон <strong>від 0% до 5%</strong>. Більшість ланцюжків майже не рухають ціну, тож високе значення не покаже майже нічого.</p><h4 id="chain-kind" tabindex="-1">Chain kind <a class="header-anchor" href="#chain-kind" aria-label="Permalink to &quot;Chain kind&quot;">​</a></h4><ul><li><strong>Qty</strong> — однакова кількість монет щоразу.</li><li><strong>Usd</strong> — однакова сума в доларах щоразу.</li><li><strong>Both</strong> (за замовчуванням).</li></ul><h4 id="max-average-gap" tabindex="-1">Max average gap <a class="header-anchor" href="#max-average-gap" aria-label="Permalink to &quot;Max average gap&quot;">​</a></h4><p>Лише ланцюжки, повтори яких у середньому віддалені не більше ніж на стільки секунд. Порожнє = вимкнено.</p><h4 id="hide-two-sided" tabindex="-1">Hide two-sided <a class="header-anchor" href="#hide-two-sided" aria-label="Permalink to &quot;Hide two-sided&quot;">​</a></h4><p>Прибирає ланцюжки, де той самий розмір повторюється й на протилежній стороні — позначені <strong>2-SIDED</strong>. За замовчуванням вимкнено.</p><h3 id="twap-venues" tabindex="-1">TWAP Venues <a class="header-anchor" href="#twap-venues" aria-label="Permalink to &quot;TWAP Venues&quot;">​</a></h3><p>Пошук TWAP працює на Kraken spot, Gate.io perp і spot, Hyperliquid, Binance, Bybit і OKX. Кожну біржу можна вимкнути й задати їй власні <strong>Min child $</strong> і <strong>Min repeats</strong>.</p><p>На Binance, Bybit і OKX серверний мінімум дочірнього ордера — <strong>$5 000</strong>. Менші повтори там узагалі не відстежуються, тож нижче налаштування на цих біржах нічого не знайде — блок повідомляє, коли це так.</p><h3 id="symbol-whitelist" tabindex="-1">Symbol whitelist <a class="header-anchor" href="#symbol-whitelist" aria-label="Permalink to &quot;Symbol whitelist&quot;">​</a></h3><p>Ці фільтри діють <strong>і на тіки, і на TWAP-ланцюжки</strong>.</p><h4 id="symbol-whitelist-1" tabindex="-1">Symbol whitelist <a class="header-anchor" href="#symbol-whitelist-1" aria-label="Permalink to &quot;Symbol whitelist&quot;">​</a></h4><p>Показувати лише ці символи. Порожній список показує всі. Введіть символ і натисніть <kbd>Enter</kbd>; кілька можна додати одразу через кому.</p><h4 id="blacklist" tabindex="-1">Blacklist <a class="header-anchor" href="#blacklist" aria-label="Permalink to &quot;Blacklist&quot;">​</a></h4><p>Символи, які ніколи не показувати. За замовчуванням: <code>BTCUSDT</code>, <code>ETHUSDT</code>, <code>BTCUSD</code>, <code>ETHUSD</code> — дві головні монети друкують великі угоди безперервно й інакше заповнили б усе вікно.</p><div class="warning custom-block"><p class="custom-block-title">Кожна біржа пише символ по-своєму</p><p>Символи порівнюються так, як їх пише біржа. Kraken надсилає <code>BTCUSD</code>, а не <code>BTCUSDT</code>. Щоб заблокувати чи відстежувати монету всюди, додайте всі її написання.</p></div><h4 id="exclude-stock-commodity-perps" tabindex="-1">Exclude stock/commodity perps <a class="header-anchor" href="#exclude-stock-commodity-perps" aria-label="Permalink to &quot;Exclude stock/commodity perps&quot;">​</a></h4><p>Прибирає XAU, XAG, TSLA та подібні токенізовані перпи. За замовчуванням вимкнено.</p><h4 id="minimum-24h-turnover" tabindex="-1">Minimum 24h turnover <a class="header-anchor" href="#minimum-24h-turnover" aria-label="Permalink to &quot;Minimum 24h turnover&quot;">​</a></h4><p>Ховає тонкі символи за 24-годинним оборотом. Діапазон <strong>від $0 до $50M</strong> з кроком $1M, за замовчуванням вимкнено. Ненульове значення також ховає символи, оборот яких ще невідомий.</p><h4 id="delivery-cap" tabindex="-1">Delivery cap <a class="header-anchor" href="#delivery-cap" aria-label="Permalink to &quot;Delivery cap&quot;">​</a></h4><p>Максимальна кількість тіків за секунду, яку сервер доставляє, перш ніж почати відкидати найменші з утримуваних. Діапазон <strong>від 1 до 200</strong>, за замовчуванням 20.</p><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><h4 id="tick-sound" tabindex="-1">Tick sound <a class="header-anchor" href="#tick-sound" aria-label="Permalink to &quot;Tick sound&quot;">​</a></h4><p>Відтворює звук, коли надходить тік, що пройшов фільтри. <strong>За замовчуванням вимкнено.</strong> З низьким мінімальним розміром це спрацьовуватиме дуже часто — спершу налаштуйте фільтри.</p><h2 id="пов-язане" tabindex="-1">Пов&#39;язане <a class="header-anchor" href="#пов-язане" aria-label="Permalink to &quot;Пов&#39;язане&quot;">​</a></h2><ul><li><a href="/manual/uk/tools/alerts.html">Alerts</a> — там живе стрічка ліквідацій</li><li><a href="/manual/uk/customize/majors.html">Шар мажорів</a> — великі угоди на графіку за ціною, де вони надрукувались</li><li><a href="/manual/uk/tools/knives.html">Knives</a> — рух на рівні свічки, а не окремі угоди</li></ul>',71))])}const f=s(h,[["render",c]]);export{q as __pageData,f as default};
